func (this *Bingx) ParseDepositWithdrawFee(fee any, optionalArgs ...any) any {
	//
	// currencie structure
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var networks any = this.SafeDict(fee, "networks", map[string]any{})
	var networkCodes []string = ObjectKeys(networks)
	var networksLength int = GetArrayLength(networkCodes)
	var result map[string]any = map[string]any{
		"info": networks,
		"withdraw": map[string]any{
			"fee":        nil,
			"percentage": nil,
		},
		"deposit": map[string]any{
			"fee":        nil,
			"percentage": nil,
		},
		"networks": map[string]any{},
	}
	if IsTrue(!IsEqual(networksLength, 0)) {
		for i := 0; IsLessThan(i, networksLength); i++ {
			var networkCode any = GetValue(networkCodes, i)
			var network any = GetValue(networks, networkCode)
			AddElementToObject(GetValue(result, "networks"), networkCode, map[string]any{
				"deposit": map[string]any{
					"fee":        nil,
					"percentage": nil,
				},
				"withdraw": map[string]any{
					"fee":        this.SafeNumber(network, "fee"),
					"percentage": false,
				},
			})
			if IsTrue(IsEqual(networksLength, 1)) {
				AddElementToObject(GetValue(result, "withdraw"), "fee", this.SafeNumber(network, "withdrawFee"))
				AddElementToObject(GetValue(result, "withdraw"), "percentage", false)
			}
		}
	}
	return result
}

